{
  "name": "pl_copy_sales_daily",
  "properties": {
    "parameters": { "runDate": { "type": "string" } },
    "activities": [
      {
        "name": "Copy sales to bronze",
        "type": "Copy",
        "policy": { "timeout": "0.02:00:00", "retry": 2, "retryIntervalInSeconds": 300 },
        "inputs": [ { "referenceName": "ds_sqlserver_sales", "type": "DatasetReference" } ],
        "outputs": [ {
          "referenceName": "ds_adls_bronze_parquet",
          "type": "DatasetReference",
          "parameters": { "folderPath": "erp/sales/ingest_date=@{pipeline().parameters.runDate}" }
        } ],
        "typeProperties": {
          "source": {
            "type": "SqlServerSource",
            "sqlReaderQuery": "SELECT * FROM dbo.sales WHERE sale_date = '@{pipeline().parameters.runDate}'"
          },
          "sink": { "type": "ParquetSink" }
        }
      }
    ]
  }
}

-- Upsert today's cleaned customers into the silver table
MERGE INTO prod.silver.customers AS t
USING (
  SELECT * FROM prod.bronze.customers_today
  QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY updated_at DESC) = 1
) AS s
ON t.customer_id = s.customer_id
WHEN MATCHED AND s.updated_at > t.updated_at THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

-- What changed, and how to look back
DESCRIBE HISTORY prod.silver.customers;
SELECT COUNT(*) FROM prod.silver.customers VERSION AS OF 41;
OPTIMIZE prod.silver.customers ZORDER BY (country);
